counters: dict[str, int] = {}

def hit(key: str) -> int:
    counters[key] = counters.get(key, 0) + 1          # zoals INCR
    if counters[key] == 1:
        print(f"  eerste hit: EXPIRE {key} {WINDOW}")
    return 429 if counters[key] > LIMIT else 200

